from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from .models import LocalizedProductCatalog

class ProductTranslationDeleteView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def delete(self, request, catalog_id, lang_code):
        # Enforce vendor ownership before permitting translation deletion
        try:
            catalog_item = LocalizedProductCatalog.objects.get(pk=catalog_id, vendor=request.user.vendor_profile)
        except LocalizedProductCatalog.DoesNotExist:
            return Response({'error': 'Product catalog item not found'}, status=status.HTTP_404_NOT_FOUND)

        catalog_item.delete_translation(lang_code)
        return Response({'status': f'Translation {lang_code} deleted successfully'}, status=status.HTTP_200_OK)
